valid-palindrome.javascript:
function is_palindrome(s) {
  let i = 0, j = s.length - 1;
  const ok = (c) => /[a-z0-9]/i.test(c);
  while (i < j) {
    while (i < j && !ok(s[i])) i++;
    while (i < j && !ok(s[j])) j--;
    if (s[i].toLowerCase() !== s[j].toLowerCase()) return false;
    i++; j--;
  }
  return true;
}

