valid-parentheses.javascript:
function is_valid(s) {
  const pair = { ")": "(", "]": "[", "}": "{" };
  const st = [];
  for (const c of s) {
    if (c in pair) { if (st.pop() !== pair[c]) return false; } else st.push(c);
  }
  return st.length === 0;
}

valid-parentheses.python:
def is_valid(s):
    pair = {')': '(', ']': '[', '}': '{'}
    st = []
    for c in s:
        if c in pair:
            if not st or st.pop() != pair[c]:
                return False
        else:
            st.append(c)
    return not st

