def length_of_longest_substring(s):
    last, left, best = {}, 0, 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = i
        best = max(best, i - left + 1)
    return best

group-anagrams.javascript:
function group_anagrams(strs) {
  const m = new Map();
  for (const w of strs) {
    const k = [...w].sort().join("");
    if (!m.has(k)) m.set(k, []);
    m.get(k).push(w);
  }
  return [...m.values()];
}

