three-sum.javascript:
function three_sum(nums) {
  const a = [...nums].sort((x, y) => x - y), out = [];
  for (let i = 0; i < a.length - 2; i++) {
    if (i > 0 && a[i] === a[i - 1]) continue;
    let l = i + 1, r = a.length - 1;
    while (l < r) {
      const s = a[i] + a[l] + a[r];
      if (s < 0) l++;
      else if (s > 0) r--;
      else { out.push([a[i], a[l], a[r]]); l++; r--; while (l < r && a[l] === a[l - 1]) l++; while (l < r && a[r] === a[r + 1]) r--; }
    }
  }
  return out;
}

three-sum.python:
def three_sum(nums):
    a = sorted(nums)
    out = []
    for i in range(len(a) - 2):
        if i > 0 and a[i] == a[i - 1]:
            continue
        l, r = i + 1, len(a) - 1
        while l < r:
            s = a[i] + a[l] + a[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                out.append([a[i], a[l], a[r]])
                l += 1
                r -= 1
                while l < r and a[l] == a[l - 1]:
                    l += 1
                while l < r and a[r] == a[r + 1]:
                    r -= 1
    return out

coin-change.javascript:
function coin_change(coins, amount) {
  const best = new Array(amount + 1).fill(Infinity);
  best[0] = 0;
  for (let x = 1; x <= amount; x++)
    for (const c of coins) if (c <= x && best[x - c] + 1 < best[x]) best[x] = best[x - c] + 1;
  return best[amount] === Infinity ? -1 : best[amount];
}

coin-change.python:
def coin_change(coins, amount):
    INF = float('inf')
    best = [0] + [INF] * amount
    for x in range(1, amount + 1):
        for c in coins:
            if c <= x and best[x - c] + 1 < best[x]:
                best[x] = best[x - c] + 1
    return -1 if best[amount] == INF else best[amount]

number-of-islands.javascript:
function num_islands(grid) {
  const g = grid.map((r) => [...r]);
  let count = 0;
  for (let r = 0; r < g.length; r++) for (let c = 0; c < g[r].length; c++) {
    if (g[r][c] !== 1) continue;
    count++;
    const stack = [[r, c]];
    g[r][c] = 0;
    while (stack.length) {
      const [y, x] = stack.pop();
      for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ny = y + dy, nx = x + dx;
        if (ny >= 0 && ny < g.length && nx >= 0 && nx < g[ny].length && g[ny][nx] === 1) { g[ny][nx] = 0; stack.push([ny, nx]); }
      }
    }
  }
  return count;
}

number-of-islands.python:
def num_islands(grid):
    g = [row[:] for row in grid]
    count = 0
    for r in range(len(g)):
        for c in range(len(g[r])):
            if g[r][c] != 1:
                continue
            count += 1
            g[r][c] = 0
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < len(g) and 0 <= nx < len(g[ny]) and g[ny][nx] == 1:
                        g[ny][nx] = 0
                        stack.append((ny, nx))
    return count

