function merge_intervals(intervals) {
  const a = intervals.map((x) => [...x]).sort((p, q) => p[0] - q[0]);
  const out = [];
  for (const cur of a) {
    const last = out[out.length - 1];
    if (last && cur[0] <= last[1]) last[1] = Math.max(last[1], cur[1]);
    else out.push(cur);
  }
  return out;
}

