function longest_palindrome_length(s) {
  let best = 0;
  const grow = (l, r) => { while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; } return r - l - 1; };
  for (let i = 0; i < s.length; i++) best = Math.max(best, grow(i, i), grow(i, i + 1));
  return best;
}

longest-palindromic-substring-length.python:
def longest_palindrome_length(s):
    best = 0
    def grow(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1
    for i in range(len(s)):
        best = max(best, grow(i, i), grow(i, i + 1))
    return best

