rotate-array.javascript:
function rotate(nums, k) {
  const n = nums.length;
  if (n === 0) return [];
  const s = k % n;
  return s === 0 ? [...nums] : [...nums.slice(n - s), ...nums.slice(0, n - s)];
}

rotate-array.python:
def rotate(nums, k):
    n = len(nums)
    if n == 0:
        return []
    s = k % n
    return nums[n - s:] + nums[:n - s] if s else nums[:]

