function trap(height) {
  let l = 0, r = height.length - 1, lm = 0, rm = 0, water = 0;
  while (l < r) {
    if (height[l] < height[r]) { lm = Math.max(lm, height[l]); water += lm - height[l]; l++; }
    else { rm = Math.max(rm, height[r]); water += rm - height[r]; r--; }
  }
  return water;
}

